import { useId, useRef, type KeyboardEvent, type ReactNode } from "react";
import "./TabStrip.css";

export interface Tab {
  id: string;
  label: string;
}

export interface TabStripProps {
  tabs: readonly Tab[];
  selected: string;
  onSelect: (id: string) => void;
  children: ReactNode;
}

export function TabStrip({ tabs, selected, onSelect, children }: TabStripProps) {
  const baseId = useId();
  const buttons = useRef<Map<string, HTMLButtonElement>>(new Map());

  const selectedIndex = tabs.findIndex((tab) => tab.id === selected);
  const activeId = selectedIndex >= 0 ? selected : tabs[0]?.id;
  const panelId = `${baseId}-panel`;

  const tabId = (id: string) => `${baseId}-tab-${id}`;

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const last = tabs.length - 1;
    let next: number;
    switch (event.key) {
      case "ArrowRight":
        next = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
        next = index === 0 ? last : index - 1;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = last;
        break;
      default:
        return;
    }
    event.preventDefault();
    const target = tabs[next];
    buttons.current.get(target.id)?.focus();
    onSelect(target.id);
  }

  return (
    <div className="tab-strip">
      <div role="tablist" className="tab-strip__list">
        {tabs.map((tab, index) => {
          const isSelected = tab.id === activeId;
          return (
            <button
              key={tab.id}
              type="button"
              role="tab"
              id={tabId(tab.id)}
              aria-selected={isSelected}
              aria-controls={panelId}
              tabIndex={isSelected ? 0 : -1}
              className="tab-strip__tab"
              ref={(el) => {
                if (el) {
                  buttons.current.set(tab.id, el);
                } else {
                  buttons.current.delete(tab.id);
                }
              }}
              onClick={() => onSelect(tab.id)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {tab.label}
            </button>
          );
        })}
      </div>
      <div
        role="tabpanel"
        id={panelId}
        aria-labelledby={activeId ? tabId(activeId) : undefined}
        tabIndex={0}
        className="tab-strip__panel"
      >
        {children}
      </div>
    </div>
  );
}
