.tab-strip__list {
  display: flex;
  gap: clamp(0.25rem, 1vw, 0.5rem);
  border-bottom: 1px solid var(--hair);
  overflow-x: auto;
}

.tab-strip__tab {
  position: relative;
  font: inherit;
