  font-weight: 400;
  color: var(--muted);
  background: none;
  border: 0;
  border-radius: 0;
  padding: 0.6rem 0.9rem;
  white-space: nowrap;
  cursor: pointer;
  transition: color 150ms ease;
}

.tab-strip__tab:hover {
  color: var(--ink);
}

.tab-strip__tab[aria-selected="true"] {
  color: var(--ink);
  font-weight: 700;
